{
  "schemaVersion": "0.2",
  "slug": "stack",
  "name": "Stack",
  "status": "experimental",
  "purpose": "One-dimensional layout primitive for spacing and alignment.",
  "scenarios": [
    "Stack form fields vertically with consistent spacing",
    "Arrange toolbar actions horizontally",
    "Align children to the end of a container"
  ],
  "props": {
    "direction": {
      "type": "enum",
      "required": false,
      "description": "Main axis of the flex container.",
      "values": [
        "row",
        "column"
      ],
      "default": "column"
    },
    "gap": {
      "type": "enum",
      "required": false,
      "description": "Spacing step applied to the gap.",
      "values": [
        "0",
        "1",
        "2",
        "3",
        "4",
        "5",
        "6"
      ],
      "default": "2"
    },
    "align": {
      "type": "enum",
      "required": false,
      "description": "Cross-axis alignment of children.",
      "values": [
        "start",
        "center",
        "end",
        "stretch"
      ],
      "default": "stretch"
    },
    "justify": {
      "type": "enum",
      "required": false,
      "description": "Main-axis distribution of children.",
      "values": [
        "start",
        "center",
        "end",
        "between"
      ],
      "default": "start"
    }
  },
  "variants": [
    {
      "name": "direction",
      "values": [
        "row",
        "column"
      ],
      "default": "column",
      "description": "Main axis of the flex container."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Flex container is rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "dialog",
      "form",
      "page"
    ],
    "allowedChildren": [
      "any"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use physical margins; use the gap prop.",
    "Do not nest deeply to avoid flexbox performance issues."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": [],
    "focus": "Stack is not focusable; it only affects layout.",
    "labeling": "Children provide their own labels.",
    "wcag": [
      "1.3.2"
    ]
  },
  "responsive": {
    "strategy": "Direction can switch at breakpoints via the direction prop; spacing is token-based.",
    "breakpoints": {
      "compact": "Stacks stay within the viewport width; gap is preserved.",
      "medium": "Direction may switch to row if space allows.",
      "large": "Direction may switch to row if space allows."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir; row follows the flow.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "stack",
    "states": [
      "row",
      "column"
    ],
    "intents": [
      "layout-flow"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export type StackDirection = 'row' | 'column'
export type StackGap = '0' | '1' | '2' | '3' | '4' | '5' | '6'
export type StackAlignment = 'start' | 'center' | 'end' | 'stretch'
export type StackJustify = 'start' | 'center' | 'end' | 'between'

export interface StackProps {
  direction?: StackDirection
  gap?: StackGap
  align?: StackAlignment
  justify?: StackJustify
  children: ReactNode
  className?: string
}

export function Stack({
  direction = 'column',
  gap = '2',
  align = 'stretch',
  justify = 'start',
  children,
  className,
}: StackProps) {
  const classes = ['cu-stack', `cu-stack--${direction}`, `cu-stack--gap-${gap}`, className]
    .filter(Boolean)
    .join(' ')

  return (
    <div
      className={classes}
      data-ai-role="stack" data-ai-intent="layout-flow"
      data-ai-state="default"
      data-direction={direction}
      data-gap={gap}
      data-align={align}
      data-justify={justify}
    >
      {children}
    </div>
  )
}

.cu-stack {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-2);
  align-items: stretch;
  justify-content: flex-start;
}

.cu-stack--row {
  flex-direction: row;
}

.cu-stack--gap-0 {
  gap: 0;
}

.cu-stack--gap-1 {
  gap: var(--cu-space-1);
}

.cu-stack--gap-2 {
  gap: var(--cu-space-2);
}

.cu-stack--gap-3 {
  gap: var(--cu-space-3);
}

.cu-stack--gap-4 {
  gap: var(--cu-space-4, 1rem);
}

.cu-stack--gap-5 {
  gap: var(--cu-space-5, 1.5rem);
}

.cu-stack--gap-6 {
  gap: var(--cu-space-6, 2.5rem);
}

.cu-stack[data-align='center'] {
  align-items: center;
}

.cu-stack[data-align='end'] {
  align-items: flex-end;
}

.cu-stack[data-align='stretch'] {
  align-items: stretch;
}

.cu-stack[data-justify='center'] {
  justify-content: center;
}

.cu-stack[data-justify='end'] {
  justify-content: flex-end;
}

.cu-stack[data-justify='between'] {
  justify-content: space-between;
}
